deepml motion 0.3
module corpus.deepml_motion.example_04001
policy deterministic
policy no_network
skeleton Rig04001 { joint Root parent none joint Hip parent Root joint FootL parent Hip joint FootR parent Hip }
procedural animation Procedural04001 seed 4001 {
  trajectory = predict_trajectory(velocity, horizon=1.0s)
  match = motion_match(database="local:motions_5", trajectory=trajectory)
  constrain contact FootL to ground when phase < 0.5
  constrain contact FootR to ground when phase >= 0.5
}
layered state_machine Layers04001 { base: Locomotion upper: Gesture additive: Breathing }
synchronize Procedural04001 with scene.Actor6 and timeline.Sequence10

